package cl.bancoxyz.account;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import java.math.BigDecimal;import org.slf4j.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;
@Service public class PaymentEventConsumer{private static final Logger log=LoggerFactory.getLogger(PaymentEventConsumer.class);private final AccountStore store;private final ObjectMapper json;public PaymentEventConsumer(AccountStore s,ObjectMapper j){store=s;json=j;}@KafkaListener(topics="${bank.events.transaction-topic:bank.transactions.completed}",groupId="account-service") public void onPayment(String message)throws Exception{JsonNode e=json.readTree(message);String type=e.path("type").asText();BigDecimal amount=e.path("amount").decimalValue();if("TRANSFER".equals(type)){store.adjust(e.path("fromAccount").asLong(),amount.negate());store.adjust(e.path("toAccount").asLong(),amount);}else if("DEPOSIT".equals(type)){store.adjust(e.path("toAccount").asLong(),amount);}else if("WITHDRAWAL".equals(type)){store.adjust(e.path("fromAccount").asLong(),amount.negate());}log.info("EVENT_APPLIED paymentId={} type={}",e.path("id").asText(),type);}}